html {
  overflow: hidden;
  background: #262626;
}

.tile {
  position: absolute;
  top: calc(50% - 1.5em);
  left: calc(50% - 1.5em);
  width: 3em;
  height: 3em;
  border-radius: 5px;
  background: #EA225E;
  animation: p 0.7s ease-in infinite alternate;
}
.tile:nth-child(n + 2) {
  animation-name: pulse1;
}
.tile:nth-child(2) {
  margin: -3.375em 3.375em;
  background: #EA225E;
  animation-delay: -1.05s;
}
